 1→package jlsm.table;
 2→
 3→import jlsm.encryption.EncryptionSpec;
 4→
 5→import java.util.Objects;
 6→
 7→/**
 8→ * Defines a named field and its type within a {@link JlsmSchema}.
 9→ *
10→ * @param name the field name; must not be null
11→ * @param type the field type; must not be null
12→ * @param encryption the encryption specification for this field; must not be null
13→ */
14→public record FieldDefinition(String name, FieldType type, EncryptionSpec encryption) {
15→
16→    /**
17→     * Compact constructor — validates all components are non-null.
18→     */
19→    public FieldDefinition {
20→        Objects.requireNonNull(name, "name must not be null");
21→        Objects.requireNonNull(type, "type must not be null");
22→        Objects.requireNonNull(encryption, "encryption must not be null");
23→    }
24→
25→    /**
26→     * Backward-compatible constructor that defaults encryption to {@link EncryptionSpec#NONE}.
27→     *
28→     * @param name the field name; must not be null
29→     * @param type the field type; must not be null
30→     */
31→    public FieldDefinition(String name, FieldType type) {
32→        this(name, type, EncryptionSpec.NONE);
33→    }
34→}
