  1→package jlsm.table.internal;
  2→
  3→import java.io.Closeable;
  4→import java.io.IOException;
  5→import java.lang.foreign.Arena;
  6→import java.lang.foreign.MemorySegment;
  7→import java.lang.foreign.ValueLayout;
  8→import java.util.ArrayList;
  9→import java.util.Arrays;
 10→import java.util.Iterator;
 11→import java.util.LinkedHashMap;
 12→import java.util.List;
 13→import java.util.Map;
 14→import java.util.Objects;
 15→
 16→import jlsm.encryption.EncryptionSpec;
 17→import jlsm.table.FieldDefinition;
 18→import jlsm.table.FieldType;
 19→import jlsm.table.IndexDefinition;
 20→import jlsm.table.IndexType;
 21→import jlsm.table.JlsmDocument;
 22→import jlsm.table.JlsmSchema;
 23→import jlsm.table.Predicate;
 24→
 25→/**
 26→ * Manages all secondary indices for a table. Routes write operations to the appropriate indices and
 27→ * provides index lookup for query execution.
 28→ */
 29→public final class IndexRegistry implements Closeable {
 30→
 31→    private final JlsmSchema schema;
 32→    private final List<SecondaryIndex> indices;
 33→    private final Map<PkKey, StoredEntry> documentStore;
 34→    private volatile boolean closed;
 35→
 36→    public IndexRegistry(JlsmSchema schema, List<IndexDefinition> definitions) throws IOException {
 37→        Objects.requireNonNull(schema, "schema");
 38→        Objects.requireNonNull(definitions, "definitions");
 39→        this.schema = schema;
 40→        this.indices = new ArrayList<>();
 41→        this.documentStore = new LinkedHashMap<>();
 42→
 43→        for (IndexDefinition def : definitions) {
 44→            validate(schema, def);
 45→            this.indices.add(createIndex(def));
 46→        }
 47→    }
 48→
 49→    public void onInsert(MemorySegment primaryKey, JlsmDocument document) throws IOException {
 50→        assert !closed : "Registry is closed";
 51→        Objects.requireNonNull(primaryKey, "primaryKey");
 52→        Objects.requireNonNull(document, "document");
 53→
 54→        // Unique checks first
 55→        for (final SecondaryIndex idx : indices) {
 56→            if (idx.definition().indexType() == IndexType.UNIQUE) {
 57→                final Object fieldValue = extractFieldValue(document, idx.definition().fieldName());
 58→                idx.onInsert(primaryKey, fieldValue);
 59→            }
 60→        }
 61→        // Non-unique inserts
 62→        for (final SecondaryIndex idx : indices) {
 63→            if (idx.definition().indexType() != IndexType.UNIQUE) {
 64→                final Object fieldValue = extractFieldValue(document, idx.definition().fieldName());
 65→                idx.onInsert(primaryKey, fieldValue);
 66→            }
 67→        }
 68→
 69→        documentStore.put(toPkKey(primaryKey), new StoredEntry(copySegment(primaryKey), document));
 70→    }
 71→
 72→    public void onUpdate(MemorySegment primaryKey, JlsmDocument oldDocument,
 73→            JlsmDocument newDocument) throws IOException {
 74→        assert !closed : "Registry is closed";
 75→        for (final SecondaryIndex idx : indices) {
 76→            final String fieldName = idx.definition().fieldName();
 77→            final Object oldValue = oldDocument != null ? extractFieldValue(oldDocument, fieldName)
 78→                    : null;
 79→            final Object newValue = extractFieldValue(newDocument, fieldName);
 80→            idx.onUpdate(primaryKey, oldValue, newValue);
 81→        }
 82→
 83→        documentStore.put(toPkKey(primaryKey),
 84→                new StoredEntry(copySegment(primaryKey), newDocument));
 85→    }
 86→
 87→    public void onDelete(MemorySegment primaryKey, JlsmDocument document) throws IOException {
 88→        assert !closed : "Registry is closed";
 89→        for (final SecondaryIndex idx : indices) {
 90→            final Object fieldValue = extractFieldValue(document, idx.definition().fieldName());
 91→            idx.onDelete(primaryKey, fieldValue);
 92→        }
 93→
 94→        documentStore.remove(toPkKey(primaryKey));
 95→    }
 96→
 97→    public SecondaryIndex findIndex(Predicate predicate) {
 98→        for (SecondaryIndex idx : indices) {
 99→            if (idx.supports(predicate)) {
100→                return idx;
101→            }
102→        }
103→        return null;
104→    }
105→
106→    public boolean isEmpty() {
107→        return indices.isEmpty();
108→    }
109→
110→    @Override
111→    public void close() throws IOException {
112→        closed = true;
113→        IOException deferred = null;
114→        for (SecondaryIndex idx : indices) {
115→            try {
116→                idx.close();
117→            } catch (IOException e) {
118→                if (deferred == null) {
119→                    deferred = e;
120→                } else {
121→                    deferred.addSuppressed(e);
122→                }
123→            }
124→        }
125→        if (deferred != null) {
126→            throw deferred;
127→        }
128→    }
129→
130→    /**
131→     * Resolves a primary key to its stored document, or null if not found.
132→     */
133→    public StoredEntry resolveEntry(MemorySegment primaryKey) {
134→        return documentStore.get(toPkKey(primaryKey));
135→    }
136→
137→    /**
138→     * Returns an iterator over all stored entries. Used for scan-and-filter queries.
139→     */
140→    public Iterator<StoredEntry> allEntries() {
141→        return List.copyOf(documentStore.values()).iterator();
142→    }
143→
144→    /**
145→     * Returns the schema this registry was created with.
146→     */
147→    public JlsmSchema schema() {
148→        return schema;
149→    }
150→
151→    // ── Document store types ────────────────────────────────────────────
152→
153→    /**
154→     * A stored entry associating a primary key segment with its document.
155→     */
156→    public record StoredEntry(MemorySegment primaryKey, JlsmDocument document) {
157→        public StoredEntry {
158→            assert primaryKey != null : "primaryKey must not be null";
159→            assert document != null : "document must not be null";
160→        }
161→    }
162→
163→    /**
164→     * Byte-array wrapper with content-based equals/hashCode for use as map keys.
165→     */
166→    private record PkKey(byte[] data) {
167→        @Override
168→        public boolean equals(Object obj) {
169→            return obj instanceof PkKey other && Arrays.equals(this.data, other.data);
170→        }
171→
172→        @Override
173→        public int hashCode() {
174→            return Arrays.hashCode(data);
175→        }
176→    }
177→
178→    private static PkKey toPkKey(MemorySegment seg) {
179→        return new PkKey(seg.toArray(ValueLayout.JAVA_BYTE));
180→    }
181→
182→    private static MemorySegment copySegment(MemorySegment src) {
183→        MemorySegment copy = Arena.ofAuto().allocate(src.byteSize());
184→        copy.copyFrom(src);
185→        return copy;
186→    }
187→
188→    // ── Private helpers ─────────────────────────────────────────────────
189→
190→    private static void validate(JlsmSchema schema, IndexDefinition def) {
191→        final int fieldIdx = schema.fieldIndex(def.fieldName());
192→        if (fieldIdx < 0) {
193→            throw new IllegalArgumentException("Field '" + def.fieldName()
194→                    + "' does not exist in schema '" + schema.name() + "'");
195→        }
196→
197→        final FieldDefinition fieldDef = schema.fields().get(fieldIdx);
198→        final FieldType fieldType = fieldDef.type();
199→
200→        switch (def.indexType()) {
201→            case RANGE, UNIQUE -> {
202→                if (fieldType == FieldType.Primitive.BOOLEAN) {
203→                    throw new IllegalArgumentException(
204→                            "RANGE/UNIQUE index is not supported on BOOLEAN field '"
205→                                    + def.fieldName() + "'");
206→                }
207→                if (!(fieldType instanceof FieldType.Primitive)) {
208→                    throw new IllegalArgumentException(
209→                            "RANGE/UNIQUE index requires a primitive field type, got: " + fieldType
210→                                    + " for field '" + def.fieldName() + "'");
211→                }
212→            }
213→            case EQUALITY -> {
214→                if (!(fieldType instanceof FieldType.Primitive)) {
215→                    throw new IllegalArgumentException(
216→                            "EQUALITY index requires a primitive field type, got: " + fieldType
217→                                    + " for field '" + def.fieldName() + "'");
218→                }
219→            }
220→            case FULL_TEXT -> {
221→                if (fieldType != FieldType.Primitive.STRING) {
222→                    throw new IllegalArgumentException(
223→                            "FULL_TEXT index requires STRING field, got: " + fieldType
224→                                    + " for field '" + def.fieldName() + "'");
225→                }
226→            }
227→            case VECTOR -> {
228→                if (!(fieldType instanceof FieldType.VectorType)) {
229→                    throw new IllegalArgumentException(
230→                            "VECTOR index requires VectorType field, got: " + fieldType
231→                                    + " for field '" + def.fieldName() + "'");
232→                }
233→            }
234→        }
235→
236→        // Validate encryption × index compatibility using the capability matrix
237→        validateEncryptionCompatibility(fieldDef, def);
238→    }
239→
240→    /**
241→     * Validates that the field's encryption specification is compatible with the requested index
242→     * type. Uses the capability methods on {@link jlsm.table.EncryptionSpec} to check support.
243→     *
244→     * @throws IllegalArgumentException if the encryption spec does not support the index type
245→     */
246→    private static void validateEncryptionCompatibility(FieldDefinition fieldDef,
247→            IndexDefinition def) {
248→        final EncryptionSpec encryption = fieldDef.encryption();
249→        assert encryption != null : "encryption must not be null (FieldDefinition enforces this)";
250→
251→        final String fieldName = def.fieldName();
252→        switch (def.indexType()) {
253→            case EQUALITY, UNIQUE -> {
254→                if (!encryption.supportsEquality()) {
255→                    throw new IllegalArgumentException(def.indexType() + " index on field '"
256→                            + fieldName + "' is incompatible with "
257→                            + encryption.getClass().getSimpleName()
258→                            + " encryption (does not support equality)");
259→                }
260→            }
261→            case RANGE -> {
262→                if (!encryption.supportsRange()) {
263→                    throw new IllegalArgumentException("RANGE index on field '" + fieldName
264→                            + "' is incompatible with " + encryption.getClass().getSimpleName()
265→                            + " encryption (does not support range queries)");
266→                }
267→            }
268→            case FULL_TEXT -> {
269→                if (!encryption.supportsKeywordSearch()) {
270→                    throw new IllegalArgumentException("FULL_TEXT index on field '" + fieldName
271→                            + "' is incompatible with " + encryption.getClass().getSimpleName()
272→                            + " encryption (does not support keyword search)");
273→                }
274→            }
275→            case VECTOR -> {
276→                if (!encryption.supportsANN()) {
277→                    throw new IllegalArgumentException("VECTOR index on field '" + fieldName
278→                            + "' is incompatible with " + encryption.getClass().getSimpleName()
279→                            + " encryption (does not support ANN)");
280→                }
281→            }
282→        }
283→    }
284→
285→    private static SecondaryIndex createIndex(IndexDefinition def) throws IOException {
286→        return switch (def.indexType()) {
287→            case EQUALITY, RANGE, UNIQUE -> new FieldIndex(def);
288→            case FULL_TEXT -> new FullTextFieldIndex(def);
289→            case VECTOR -> new VectorFieldIndex(def);
290→        };
291→    }
292→
293→    private Object extractFieldValue(JlsmDocument document, String fieldName) {
294→        if (document.isNull(fieldName)) {
295→            return null;
296→        }
297→        final int idx = schema.fieldIndex(fieldName);
298→        assert idx >= 0 : "Field must exist — validated at construction";
299→        final FieldDefinition fieldDef = schema.fields().get(idx);
300→        final FieldType fieldType = fieldDef.type();
301→
302→        if (fieldType instanceof FieldType.Primitive p) {
303→            return switch (p) {
304→                case STRING -> document.getString(fieldName);
305→                case INT8 -> document.getByte(fieldName);
306→                case INT16 -> document.getShort(fieldName);
307→                case INT32 -> document.getInt(fieldName);
308→                case INT64 -> document.getLong(fieldName);
309→                case FLOAT16 -> document.getFloat16Bits(fieldName);
310→                case FLOAT32 -> document.getFloat(fieldName);
311→                case FLOAT64 -> document.getDouble(fieldName);
312→                case BOOLEAN -> document.getBoolean(fieldName);
313→                case TIMESTAMP -> document.getTimestamp(fieldName);
314→            };
315→        } else if (fieldType instanceof FieldType.ArrayType) {
316→            return document.getArray(fieldName);
317→        } else if (fieldType instanceof FieldType.VectorType) {
318→            return DocumentAccess.get().values(document)[idx];
319→        } else if (fieldType instanceof FieldType.ObjectType) {
320→            return document.getObject(fieldName);
321→        }
322→        return null;
323→    }
324→}
