  1→package jlsm.encryption;
  2→
  3→import java.security.GeneralSecurityException;
  4→import java.util.Objects;
  5→
  6→import javax.crypto.Cipher;
  7→import javax.crypto.spec.SecretKeySpec;
  8→
  9→/**
 10→ * Contract: Order-preserving encryption using the Boldyreva scheme with hypergeometric sampling.
 11→ * Stateless and key-only — no mutable state required. Maps a plaintext domain {@code [1..M]} to a
 12→ * ciphertext range {@code [1..N]} where {@code N >> M}, preserving ordering: if {@code a < b} then
 13→ * {@code encrypt(a) < encrypt(b)}.
 14→ *
 15→ * <p>
 16→ * Uses recursive bisection with key-seeded pseudorandom coin from AES-based PRF to sample from the
 17→ * hypergeometric distribution, mapping each plaintext to a unique ciphertext preserving order.
 18→ *
 19→ * <p>
 20→ * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 21→ */
 22→public final class BoldyrevaOpeEncryptor {
 23→
 24→    private static final int MAX_RECURSION_DEPTH = 128;
 25→    private static final int BLOCK_SIZE = 16;
 26→
 27→    private final long domainSize;
 28→    private final long rangeSize;
 29→
 30→    /** Cached AES/ECB cipher — stateless between doFinal calls, safe to reuse without re-init. */
 31→    private final Cipher prfCipher;
 32→
 33→    /** Reusable 16-byte buffer for PRF input assembly. */
 34→    private final byte[] prfBuffer = new byte[BLOCK_SIZE];
 35→
 36→    /**
 37→     * Creates a Boldyreva OPE encryptor with the given key and domain/range configuration.
 38→     *
 39→     * @param keyHolder the key holder providing key material
 40→     * @param domainSize the plaintext domain size M (values in [1..M])
 41→     * @param rangeSize the ciphertext range size N (values in [1..N], must be {@code > domainSize})
 42→     * @throws IllegalArgumentException if rangeSize is not greater than domainSize, or domainSize <
 43→     *             1
 44→     */
 45→    public BoldyrevaOpeEncryptor(EncryptionKeyHolder keyHolder, long domainSize, long rangeSize) {
 46→        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
 47→        if (domainSize < 1) {
 48→            throw new IllegalArgumentException("domainSize must be >= 1, got " + domainSize);
 49→        }
 50→        if (rangeSize <= domainSize) {
 51→            throw new IllegalArgumentException("rangeSize must be > domainSize, got rangeSize="
 52→                    + rangeSize + " domainSize=" + domainSize);
 53→        }
 54→        final byte[] keyBytes = keyHolder.getKeyBytes();
 55→        this.domainSize = domainSize;
 56→        this.rangeSize = rangeSize;
 57→
 58→        try {
 59→            this.prfCipher = Cipher.getInstance("AES/ECB/NoPadding");
 60→            final SecretKeySpec prfKeySpec = new SecretKeySpec(keyBytes, 0,
 61→                    Math.min(keyBytes.length, 32), "AES");
 62→            this.prfCipher.init(Cipher.ENCRYPT_MODE, prfKeySpec);
 63→        } catch (GeneralSecurityException e) {
 64→            throw new IllegalStateException("Failed to initialize AES PRF cipher", e);
 65→        }
 66→    }
 67→
 68→    /**
 69→     * Encrypts a plaintext value, preserving order.
 70→     *
 71→     * @param plaintext the value to encrypt; must be in {@code [1..domainSize]}
 72→     * @return the encrypted value in {@code [1..rangeSize]}
 73→     * @throws IllegalArgumentException if plaintext is out of domain bounds
 74→     */
 75→    public long encrypt(long plaintext) {
 76→        if (plaintext < 1 || plaintext > domainSize) {
 77→            throw new IllegalArgumentException(
 78→                    "Plaintext must be in [1.." + domainSize + "], got " + plaintext);
 79→        }
 80→        return encryptRecursive(plaintext, 1, domainSize, 1, rangeSize, 0);
 81→    }
 82→
 83→    /**
 84→     * Decrypts a ciphertext value via binary search.
 85→     *
 86→     * @param ciphertext the encrypted value; must be in {@code [1..rangeSize]}
 87→     * @return the original plaintext in {@code [1..domainSize]}
 88→     * @throws IllegalArgumentException if ciphertext is out of range bounds
 89→     */
 90→    public long decrypt(long ciphertext) {
 91→        if (ciphertext < 1 || ciphertext > rangeSize) {
 92→            throw new IllegalArgumentException(
 93→                    "Ciphertext must be in [1.." + rangeSize + "], got " + ciphertext);
 94→        }
 95→        // Binary search: find plaintext p such that encrypt(p) == ciphertext
 96→        long lo = 1;
 97→        long hi = domainSize;
 98→        while (lo <= hi) {
 99→            final long mid = lo + (hi - lo) / 2;
100→            final long enc = encrypt(mid);
101→            if (enc == ciphertext) {
102→                return mid;
103→            } else if (enc < ciphertext) {
104→                lo = mid + 1;
105→            } else {
106→                hi = mid - 1;
107→            }
108→        }
109→        throw new IllegalArgumentException("No plaintext maps to ciphertext " + ciphertext
110→                + " in the configured domain/range");
111→    }
112→
113→    // ── Recursive bisection (Boldyreva lazy-sample) ─────────────────────────
114→
115→    /**
116→     * Recursively maps plaintext m in [dLo..dHi] to ciphertext in [rLo..rHi]. At each step, pick
117→     * midpoint of the range, sample a "coin" from HG distribution to decide how many domain values
118→     * fall in the left half, then recurse into the appropriate half.
119→     */
120→    private long encryptRecursive(long plaintext, long dLo, long dHi, long rLo, long rHi,
121→            int depth) {
122→        assert dLo <= dHi : "domain lo > hi";
123→        assert rLo <= rHi : "range lo > hi";
124→        assert depth <= MAX_RECURSION_DEPTH : "max recursion depth exceeded at " + depth;
125→
126→        final long dSize = dHi - dLo + 1;
127→        final long rSize = rHi - rLo + 1;
128→
129→        if (dSize == 1) {
130→            // Single domain value — map to midpoint of remaining range
131→            return rLo + rSize / 2;
132→        }
133→
134→        // Midpoint of range
135→        final long rMid = rLo + (rSize - 1) / 2;
136→        final long rLeftSize = rMid - rLo + 1;
137→
138→        // Sample how many domain values land in the left half [rLo..rMid]
139→        // using HG(rSize, dSize, rLeftSize) seeded by key + (dLo, dHi, rLo, rHi)
140→        final long dLeftCount = sampleHypergeometric(rSize, dSize, rLeftSize, dLo, dHi, rLo, rHi);
141→
142→        if (plaintext <= dLo + dLeftCount - 1) {
143→            // Plaintext is in the left partition
144→            return encryptRecursive(plaintext, dLo, dLo + dLeftCount - 1, rLo, rMid, depth + 1);
145→        } else {
146→            // Plaintext is in the right partition
147→            return encryptRecursive(plaintext, dLo + dLeftCount, dHi, rMid + 1, rHi, depth + 1);
148→        }
149→    }
150→
151→    /**
152→     * Samples from the hypergeometric distribution HG(N, K, n) using an AES-based PRF coin.
153→     *
154→     * Population N = rangeSegmentSize, success states K = domainSegmentSize, draws n =
155→     * leftRangeSize.
156→     *
157→     * Returns the number of domain values that fall in the left range partition. Uses the
158→     * sequential sampling algorithm (Fisher-Yates style).
159→     */
160→    private long sampleHypergeometric(long popN, long succK, long draws, long dLo, long dHi,
161→            long rLo, long rHi) {
162→        assert popN > 0 : "population must be positive";
163→        assert succK >= 0 && succK <= popN : "succK out of bounds";
164→        assert draws >= 0 && draws <= popN : "draws out of bounds";
165→
166→        // Derive a deterministic seed for this particular node from key + parameters
167→        final long nodeSeed = prfSeed(dLo, dHi, rLo, rHi);
168→
169→        // Sequential sampling: iterate through draws, each time flipping a coin
170→        long population = popN;
171→        long successes = succK;
172→        long selected = 0;
173→        long coinState = nodeSeed;
174→
175→        for (long i = 0; i < draws && successes > 0; i++) {
176→            // Probability of selecting a success: successes / population
177→            // Use PRF coin to decide
178→            coinState = prfNext(coinState, i);
179→            final double threshold = (double) successes / (double) population;
180→            final double coin = pseudoUniform(coinState);
181→
182→            if (coin < threshold) {
183→                selected++;
184→                successes--;
185→            }
186→            population--;
187→        }
188→
189→        return selected;
190→    }
191→
192→    /**
193→     * Derives a deterministic seed from the key and node parameters using AES encryption. Uses
194→     * cached prfCipher — AES/ECB is stateless between doFinal calls.
195→     */
196→    private long prfSeed(long dLo, long dHi, long rLo, long rHi) {
197→        try {
198→            // Pack 4 ints into prfBuffer (big-endian, matching original ByteBuffer.putInt behavior)
199→            final int i0 = (int) (dLo ^ (dLo >>> 32));
200→            final int i1 = (int) (dHi ^ (dHi >>> 32));
201→            final int i2 = (int) (rLo ^ (rLo >>> 32));
202→            final int i3 = (int) (rHi ^ (rHi >>> 32));
203→
204→            prfBuffer[0] = (byte) (i0 >>> 24);
205→            prfBuffer[1] = (byte) (i0 >>> 16);
206→            prfBuffer[2] = (byte) (i0 >>> 8);
207→            prfBuffer[3] = (byte) i0;
208→            prfBuffer[4] = (byte) (i1 >>> 24);
209→            prfBuffer[5] = (byte) (i1 >>> 16);
210→            prfBuffer[6] = (byte) (i1 >>> 8);
211→            prfBuffer[7] = (byte) i1;
212→            prfBuffer[8] = (byte) (i2 >>> 24);
213→            prfBuffer[9] = (byte) (i2 >>> 16);
214→            prfBuffer[10] = (byte) (i2 >>> 8);
215→            prfBuffer[11] = (byte) i2;
216→            prfBuffer[12] = (byte) (i3 >>> 24);
217→            prfBuffer[13] = (byte) (i3 >>> 16);
218→            prfBuffer[14] = (byte) (i3 >>> 8);
219→            prfBuffer[15] = (byte) i3;
220→
221→            final byte[] encrypted = prfCipher.doFinal(prfBuffer);
222→            assert encrypted.length == BLOCK_SIZE : "AES block output must be 16 bytes";
223→            return ((long) (encrypted[0] & 0xFF) << 56) | ((long) (encrypted[1] & 0xFF) << 48)
224→                    | ((long) (encrypted[2] & 0xFF) << 40) | ((long) (encrypted[3] & 0xFF) << 32)
225→                    | ((long) (encrypted[4] & 0xFF) << 24) | ((long) (encrypted[5] & 0xFF) << 16)
226→                    | ((long) (encrypted[6] & 0xFF) << 8) | ((long) (encrypted[7] & 0xFF));
227→        } catch (GeneralSecurityException e) {
228→            throw new IllegalStateException("AES PRF failed", e);
229→        }
230→    }
231→
232→    /**
233→     * Derives the next PRF state from current state and iteration. Uses cached prfCipher — AES/ECB
234→     * is stateless between doFinal calls.
235→     */
236→    private long prfNext(long state, long iteration) {
237→        try {
238→            // Pack 2 longs into prfBuffer (big-endian, matching original ByteBuffer.putLong
239→            // behavior)
240→            prfBuffer[0] = (byte) (state >>> 56);
241→            prfBuffer[1] = (byte) (state >>> 48);
242→            prfBuffer[2] = (byte) (state >>> 40);
243→            prfBuffer[3] = (byte) (state >>> 32);
244→            prfBuffer[4] = (byte) (state >>> 24);
245→            prfBuffer[5] = (byte) (state >>> 16);
246→            prfBuffer[6] = (byte) (state >>> 8);
247→            prfBuffer[7] = (byte) state;
248→            prfBuffer[8] = (byte) (iteration >>> 56);
249→            prfBuffer[9] = (byte) (iteration >>> 48);
250→            prfBuffer[10] = (byte) (iteration >>> 40);
251→            prfBuffer[11] = (byte) (iteration >>> 32);
252→            prfBuffer[12] = (byte) (iteration >>> 24);
253→            prfBuffer[13] = (byte) (iteration >>> 16);
254→            prfBuffer[14] = (byte) (iteration >>> 8);
255→            prfBuffer[15] = (byte) iteration;
256→
257→            final byte[] encrypted = prfCipher.doFinal(prfBuffer);
258→            assert encrypted.length == BLOCK_SIZE : "AES block output must be 16 bytes";
259→            return ((long) (encrypted[0] & 0xFF) << 56) | ((long) (encrypted[1] & 0xFF) << 48)
260→                    | ((long) (encrypted[2] & 0xFF) << 40) | ((long) (encrypted[3] & 0xFF) << 32)
261→                    | ((long) (encrypted[4] & 0xFF) << 24) | ((long) (encrypted[5] & 0xFF) << 16)
262→                    | ((long) (encrypted[6] & 0xFF) << 8) | ((long) (encrypted[7] & 0xFF));
263→        } catch (GeneralSecurityException e) {
264→            throw new IllegalStateException("AES PRF failed", e);
265→        }
266→    }
267→
268→    /**
269→     * Maps a long to a pseudo-uniform double in [0, 1).
270→     */
271→    private static double pseudoUniform(long value) {
272→        return (double) (value >>> 1) / (double) Long.MAX_VALUE;
273→    }
274→}
