336→    /**
337→     * Validates that {@code value} is compatible with {@code type}.
338→     *
339→     * @param fieldName the field name (for error messages)
340→     * @param type the declared field type
341→     * @param value the non-null value to check
342→     * @throws IllegalArgumentException if the value type does not match
343→     */
344→    private static void validateType(String fieldName, FieldType type, Object value) {
345→        assert fieldName != null : "fieldName must not be null";
346→        assert type != null : "type must not be null";
347→        assert value != null : "value must not be null (nulls are handled by callers)";
348→
349→        switch (type) {
350→            case FieldType.Primitive p -> {
351→                switch (p) {
352→                    case STRING -> expect(fieldName, value, String.class, "STRING");
353→                    case INT8 -> expect(fieldName, value, Byte.class, "INT8");
354→                    case INT16 -> expect(fieldName, value, Short.class, "INT16");
355→                    case INT32 -> expect(fieldName, value, Integer.class, "INT32");
356→                    case INT64 -> expect(fieldName, value, Long.class, "INT64");
357→                    case FLOAT16 -> expect(fieldName, value, Short.class, "FLOAT16");
358→                    case FLOAT32 -> expect(fieldName, value, Float.class, "FLOAT32");
359→                    case FLOAT64 -> expect(fieldName, value, Double.class, "FLOAT64");
360→                    case BOOLEAN -> expect(fieldName, value, Boolean.class, "BOOLEAN");
361→                    case TIMESTAMP -> expect(fieldName, value, Long.class, "TIMESTAMP");
362→                }
363→            }
364→            case FieldType.ArrayType _ -> expect(fieldName, value, Object[].class, "ARRAY");
365→            case FieldType.VectorType vt -> {
366→                if (vt.elementType() == FieldType.Primitive.FLOAT32) {
367→                    expect(fieldName, value, float[].class, "VECTOR(FLOAT32)");
368→                    final float[] fArr = (float[]) value;
369→                    if (fArr.length != vt.dimensions()) {
370→                        throw new IllegalArgumentException("Field '" + fieldName
371→                                + "' expects VECTOR(FLOAT32, " + vt.dimensions() + ") but got "
372→                                + fArr.length + " elements");
373→                    }
374→                } else {
375→                    expect(fieldName, value, short[].class, "VECTOR(FLOAT16)");
376→                    final short[] sArr = (short[]) value;
377→                    if (sArr.length != vt.dimensions()) {
378→                        throw new IllegalArgumentException("Field '" + fieldName
379→                                + "' expects VECTOR(FLOAT16, " + vt.dimensions() + ") but got "
380→                                + sArr.length + " elements");
381→                    }
382→                }
383→            }
384→            case FieldType.ObjectType _ -> expect(fieldName, value, JlsmDocument.class, "OBJECT");
385→        }
386→    }
387→
388→    private static void expect(String fieldName, Object value, Class<?> expectedClass,
389→            String typeName) {
390→        if (!expectedClass.isInstance(value)) {
391→            throw new IllegalArgumentException("Field '" + fieldName + "' expects " + typeName
392→                    + " (" + expectedClass.getSimpleName() + "), got "
393→                    + value.getClass().getSimpleName());
394→        }
395→    }
