 12→/**
 13→ * Encodes field values into sort-preserving binary form for secondary index keys.
 14→ *
 15→ * <p>
 16→ * Encoding rules (sort-preserving):
 17→ * <ul>
 18→ * <li>INT8/INT16/INT32/INT64: sign-bit-flipped big-endian</li>
 19→ * <li>FLOAT32/FLOAT64: IEEE 754 sort-preserving encoding</li>
 20→ * <li>FLOAT16: sign-bit-flipped big-endian on the 2-byte representation</li>
 21→ * <li>STRING: UTF-8 bytes</li>
 22→ * <li>BOOLEAN: 0x00 for false, 0x01 for true</li>
 23→ * <li>TIMESTAMP: same as INT64 (epoch millis)</li>
 24→ * </ul>
 25→ */
 26→public final class FieldValueCodec {
 27→
 28→    private static final ValueLayout.OfByte BE_BYTE = ValueLayout.JAVA_BYTE
 29→            .withOrder(ByteOrder.BIG_ENDIAN);
 30→    private static final ValueLayout.OfShort BE_SHORT = ValueLayout.JAVA_SHORT_UNALIGNED
 31→            .withOrder(ByteOrder.BIG_ENDIAN);
 32→    private static final ValueLayout.OfInt BE_INT = ValueLayout.JAVA_INT_UNALIGNED
 33→            .withOrder(ByteOrder.BIG_ENDIAN);
 34→    private static final ValueLayout.OfLong BE_LONG = ValueLayout.JAVA_LONG_UNALIGNED
 35→            .withOrder(ByteOrder.BIG_ENDIAN);
 36→
 37→    private FieldValueCodec() {
 38→    }
 39→
 40→    public static MemorySegment encode(Object value, FieldType fieldType) {
 41→        Objects.requireNonNull(fieldType, "fieldType");
 42→        if (!(fieldType instanceof FieldType.Primitive p)) {
 43→            throw new IllegalArgumentException(
 44→                    "Only primitive field types can be encoded, got: " + fieldType);
 45→        }
 46→        Objects.requireNonNull(value, "value");
 47→        return switch (p) {
 48→            case INT8 -> encodeInt8(value);
 49→            case INT16 -> encodeInt16(value);
 50→            case INT32 -> encodeInt32(value);
 51→            case INT64 -> encodeInt64(value);
 52→            case FLOAT16 -> encodeFloat16(value);
 53→            case FLOAT32 -> encodeFloat32(value);
 54→            case FLOAT64 -> encodeFloat64(value);
 55→            case STRING -> encodeString(value);
 56→            case BOOLEAN -> encodeBoolean(value);
 57→            case TIMESTAMP -> encodeTimestamp(value);
 58→        };
 59→    }
 60→
 61→    public static Object decode(MemorySegment encoded, FieldType fieldType) {
 62→        Objects.requireNonNull(encoded, "encoded");
 63→        Objects.requireNonNull(fieldType, "fieldType");
 64→        if (!(fieldType instanceof FieldType.Primitive p)) {
 65→            throw new IllegalArgumentException(
 66→                    "Only primitive field types can be decoded, got: " + fieldType);
 67→        }
 68→        return switch (p) {
 69→            case INT8 -> decodeInt8(encoded);
 70→            case INT16 -> decodeInt16(encoded);
 71→            case INT32 -> decodeInt32(encoded);
 72→            case INT64 -> decodeInt64(encoded);
 73→            case FLOAT16 -> decodeFloat16(encoded);
 74→            case FLOAT32 -> decodeFloat32(encoded);
 75→            case FLOAT64 -> decodeFloat64(encoded);
 76→            case STRING -> decodeString(encoded);
 77→            case BOOLEAN -> decodeBoolean(encoded);
 78→            case TIMESTAMP -> decodeTimestamp(encoded);
 79→        };
 80→    }
