385→    private static int measureField(FieldType type, Object value) {
386→        return switch (type) {
387→            case FieldType.Primitive p -> switch (p) {
388→                case STRING -> {
389→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
390→                    yield varIntSize(utf8.length) + utf8.length;
391→                }
392→                case INT8 -> 1;
393→                case INT16 -> 2;
394→                case INT32 -> 4;
395→                case INT64 -> 8;
396→                case FLOAT16 -> 2;
397→                case FLOAT32 -> 4;
398→                case FLOAT64 -> 8;
399→                case BOOLEAN -> 0; // packed in bitmask
400→                case TIMESTAMP -> 8;
401→            };
402→            case FieldType.ArrayType at -> {
403→                final Object[] arr = (Object[]) value;
404→                int sz = varIntSize(arr.length);
405→                for (Object elem : arr) {
406→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
407→                }
408→                yield sz;
409→            }
410→            case FieldType.VectorType vt -> {
411→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
412→                yield vt.dimensions() * elemBytes;
413→            }
414→            case FieldType.ObjectType ot -> {
415→                final JlsmDocument sub = (JlsmDocument) value;
416→                final List<FieldDefinition> subFields = ot.fields();
417→                final int subBoolCount = countBoolFields(subFields);
418→                final int subNullBytes = (subFields.size() + 7) / 8;
419→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
420→                int sz = subNullBytes + subBoolBytes;
421→                sz += measureFields(subFields, sub.values());
422→                yield sz;
423→            }
424→        };
425→    }
