431→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
432→        for (int i = 0; i < fields.size(); i++) {
433→            final Object val = values[i];
434→            if (val == null) {
435→                continue;
436→            }
437→            encodeField(c, fields.get(i).type(), val);
438→        }
439→    }
440→
441→    /**
442→     * Measures payload size when some fields are pre-encrypted. Encrypted fields are stored as
443→     * varint-length-prefixed blobs; unencrypted fields use standard measurement.
444→     */
445→    private static int measureFieldsWithEncryption(List<FieldDefinition> fields, Object[] values,
446→            byte[][] encryptedPayloads) {
447→        int total = 0;
448→        for (int i = 0; i < fields.size(); i++) {
449→            final Object val = values[i];
450→            if (val == null) {
451→                continue; // null → no value bytes
452→            }
453→            if (encryptedPayloads[i] != null) {
454→                // Length-prefixed encrypted blob
455→                total += varIntSize(encryptedPayloads[i].length) + encryptedPayloads[i].length;
456→            } else {
457→                total += measureField(fields.get(i).type(), val);
458→            }
459→        }
460→        return total;
461→    }
