463→    /**
464→     * Encodes fields with encryption support. Encrypted fields are written as
465→     * varint-length-prefixed blobs from the pre-encrypted payloads; unencrypted fields use the
466→     * standard encode path.
467→     */
468→    private static void encodeFieldsWithEncryption(List<FieldDefinition> fields, Object[] values,
469→            byte[][] encryptedPayloads, Cursor c) {
470→        for (int i = 0; i < fields.size(); i++) {
471→            final Object val = values[i];
472→            if (val == null) {
473→                continue;
474→            }
475→            if (encryptedPayloads[i] != null) {
476→                // Write length-prefixed encrypted blob
477→                final byte[] enc = encryptedPayloads[i];
478→                writeVarInt(c, enc.length);
479→                System.arraycopy(enc, 0, c.buf, c.pos, enc.length);
480→                c.pos += enc.length;
481→            } else {
482→                encodeField(c, fields.get(i).type(), val);
483→            }
484→        }
485→    }
