487→    /**
488→     * Serializes a single field value into a fresh byte array. Used to produce the plaintext bytes
489→     * that will be fed to the field encryptor.
490→     */
491→    private static byte[] serializeFieldToBytes(FieldType type, Object value) {
492→        assert value != null : "value must not be null for serialization";
493→        final int size = measureField(type, value);
494→        final byte[] buf = new byte[size];
495→        final Cursor c = new Cursor(buf, 0);
496→        encodeField(c, type, value);
497→        assert c.pos == size : "encoded size mismatch: expected " + size + ", got " + c.pos;
498→        return buf;
499→    }
