// -- OPE type-aware helpers -----------------------------------------------

/**
 * Type-aware OPE encryption. Encodes the plaintext bytes as a positive long in the
 * natural domain of the field type (e.g., [1..256] for INT8), encrypts with OPE,
 * and returns the ciphertext as an 8-byte big-endian long.
 *
 * <p>The encoding treats the byte array as an unsigned big-endian integer, adds 1
 * (to ensure minimum value of 1 for OPE domain), and truncates to maxBytes worth
 * of data to stay within the configured domain.
 */
private static byte[] opeEncryptTyped(BoldyrevaOpeEncryptor ope, byte[] plaintext,
        int maxBytes) {
    final long value = bytesToUnsignedLong(plaintext, maxBytes) + 1; // +1: OPE domain starts at 1
    final long encrypted = ope.encrypt(value);
    return longToBytes(encrypted);
}

/**
 * Type-aware OPE decryption. Decrypts the 8-byte ciphertext, subtracts 1 (to reverse
 * the +1 offset), and converts back to a byte array of the original length.
 */
private static byte[] opeDecryptTyped(BoldyrevaOpeEncryptor ope, byte[] ciphertext,
        int maxBytes) {
    final long encValue = bytesTo8ByteLong(ciphertext);
    final long decrypted = ope.decrypt(encValue) - 1; // undo +1 offset
    return unsignedLongToBytes(decrypted, maxBytes);
}

/**
 * Interprets up to {@code maxBytes} bytes from the input as an unsigned big-endian
 * integer. If the input is shorter than maxBytes, it is left-padded with zeros.
 * If longer, only the first maxBytes bytes are used.
 */
private static long bytesToUnsignedLong(byte[] data, int maxBytes) {
    assert data != null : "data must not be null";
    final int useBytes = Math.min(data.length, maxBytes);
    long result = 0;
    for (int i = 0; i < useBytes; i++) {
        result = (result << 8) | (data[i] & 0xFFL);
    }
    // Left-pad with zeros if data is shorter than maxBytes (already handled by initial 0)
    // But we need to shift left for any remaining positions
    result <<= (8 * (maxBytes - useBytes));
    // Un-shift: actually we want the value to match the data, not be shifted.
    // Re-think: for a 1-byte value {42} with maxBytes=1, result should be 42.
    // For a 2-byte value {0x01, 0x23} with maxBytes=2, result should be 0x0123 = 291.
    // The above logic already handles this correctly for useBytes == maxBytes.
    // For useBytes < maxBytes, the data occupies the high bytes (preserving sort order).
    return result;
}

/**
 * Converts an unsigned long value back to a byte array of the given length.
 * This reverses the encoding done by {@link #bytesToUnsignedLong(byte[], int)}.
 */
private static byte[] unsignedLongToBytes(long value, int byteCount) {
    assert byteCount >= 1 && byteCount <= 8 : "byteCount must be in [1..8]";
    final byte[] result = new byte[byteCount];
    for (int i = byteCount - 1; i >= 0; i--) {
        result[i] = (byte) (value & 0xFF);
        value >>>= 8;
    }
    return result;
}

private static byte[] longToBytes(long value) {
    final byte[] buf = new byte[8];
